import{_ as a}from"./chunks/plugin-vue_export-helper.DlAUqK2U.js";import{c as r,o as n,af as e}from"./chunks/mermaid.DrCHRkU0.js";import"./chunks/cytoscape.C2CwDKBM.js";import"./chunks/dayjs.C32PoDnw.js";const m=JSON.parse('{"title":"Agent Design Patterns 学习笔记","description":"","frontmatter":{},"headers":[],"relativePath":"tech/patterns/agent/agent-design-patterns.md","filePath":"tech/patterns/agent/agent-design-patterns.md","lastUpdated":1780925353000}'),o={name:"tech/patterns/agent/agent-design-patterns.md"};function d(s,t,i,l,g,h){return n(),r("div",null,[...t[0]||(t[0]=[e(`<h1 id="agent-design-patterns-学习笔记" tabindex="-1">Agent Design Patterns 学习笔记 <a class="header-anchor" href="#agent-design-patterns-学习笔记" aria-label="Permalink to &quot;Agent Design Patterns 学习笔记&quot;">​</a></h1><blockquote><p>来源: <a href="https://adp.xindoo.xyz/" target="_blank" rel="noreferrer">Agentic Design Patterns 中文翻译项目</a> by xindoo 学习日期: 2026-04-12</p></blockquote><h2 id="概述" tabindex="-1">概述 <a class="header-anchor" href="#概述" aria-label="Permalink to &quot;概述&quot;">​</a></h2><p>《Agentic Design Patterns》系统介绍了 AI Agent 系统的 21 个核心设计模式，涵盖从基础到高级的完整体系。</p><hr><h2 id="_21-个核心模式速览" tabindex="-1">21 个核心模式速览 <a class="header-anchor" href="#_21-个核心模式速览" aria-label="Permalink to &quot;21 个核心模式速览&quot;">​</a></h2><h3 id="基础模式-1-3" tabindex="-1">基础模式 (1-3) <a class="header-anchor" href="#基础模式-1-3" aria-label="Permalink to &quot;基础模式 (1-3)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>#</th><th>模式</th><th>核心思想</th></tr></thead><tbody><tr><td>1</td><td><strong>Prompt Chaining</strong></td><td>将复杂任务分解为顺序步骤，每步输出作为下一步输入</td></tr><tr><td>2</td><td><strong>Routing</strong></td><td>根据输入特征/意图动态选择不同处理路径</td></tr><tr><td>3</td><td><strong>Parallelization</strong></td><td>并行处理独立子任务以提升吞吐量</td></tr></tbody></table><h3 id="进阶模式-4-7" tabindex="-1">进阶模式 (4-7) <a class="header-anchor" href="#进阶模式-4-7" aria-label="Permalink to &quot;进阶模式 (4-7)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>#</th><th>模式</th><th>核心思想</th></tr></thead><tbody><tr><td>4</td><td><strong>Reflection</strong></td><td>Agent 自我审视输出质量，自我修正</td></tr><tr><td>5</td><td><strong>Tool Use</strong></td><td>LLM 调用外部工具扩展能力</td></tr><tr><td>6</td><td><strong>Planning</strong></td><td>主动分解目标并规划执行步骤</td></tr><tr><td>7</td><td><strong>Multi-Agent Collaboration</strong></td><td>多 Agent 协作分工</td></tr></tbody></table><h3 id="高级模式-8-13" tabindex="-1">高级模式 (8-13) <a class="header-anchor" href="#高级模式-8-13" aria-label="Permalink to &quot;高级模式 (8-13)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>#</th><th>模式</th><th>核心思想</th></tr></thead><tbody><tr><td>8</td><td><strong>Memory Management</strong></td><td>短期/长期记忆的存储与检索策略</td></tr><tr><td>9</td><td><strong>Learning and Adaptation</strong></td><td>从交互中持续学习和适应</td></tr><tr><td>10</td><td><strong>Model Context Protocol (MCP)</strong></td><td>标准化的上下文协议</td></tr><tr><td>11</td><td><strong>Goal Setting and Monitoring</strong></td><td>目标设定与执行监控</td></tr><tr><td>12</td><td><strong>Exception Handling and Recovery</strong></td><td>异常检测与恢复机制</td></tr><tr><td>13</td><td><strong>Human-in-the-Loop</strong></td><td>人类介入的关键节点设计</td></tr></tbody></table><h3 id="应用与安全模式-14-21" tabindex="-1">应用与安全模式 (14-21) <a class="header-anchor" href="#应用与安全模式-14-21" aria-label="Permalink to &quot;应用与安全模式 (14-21)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>#</th><th>模式</th><th>核心思想</th></tr></thead><tbody><tr><td>14</td><td><strong>Knowledge Retrieval (RAG)</strong></td><td>知识检索增强生成</td></tr><tr><td>15</td><td><strong>Inter-Agent Communication (A2A)</strong></td><td>Agent 间通信协议</td></tr><tr><td>16</td><td><strong>Resource-Aware Optimization</strong></td><td>资源感知的成本优化</td></tr><tr><td>17</td><td><strong>Reasoning Techniques</strong></td><td>推理技术（CoT/ToT 等）</td></tr><tr><td>18</td><td><strong>Guardrails/Safety Patterns</strong></td><td>安全防护与内容过滤</td></tr><tr><td>19</td><td><strong>Evaluation and Monitoring</strong></td><td>Agent 系统评估与监控</td></tr><tr><td>20</td><td><strong>Prioritization</strong></td><td>任务优先级排序</td></tr><tr><td>21</td><td><strong>Exploration and Discovery</strong></td><td>探索与发现新模式</td></tr></tbody></table><hr><h2 id="核心模式详解" tabindex="-1">核心模式详解 <a class="header-anchor" href="#核心模式详解" aria-label="Permalink to &quot;核心模式详解&quot;">​</a></h2><h3 id="_1-prompt-chaining-提示词链" tabindex="-1">1. Prompt Chaining（提示词链） <a class="header-anchor" href="#_1-prompt-chaining-提示词链" aria-label="Permalink to &quot;1. Prompt Chaining（提示词链）&quot;">​</a></h3><p><strong>适用场景</strong>: 复杂多步骤任务，单一 Prompt 容易出现指令忽略、上下文偏离、错误传播</p><p><strong>典型流程</strong>:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>用户查询 → 分析(LLM) → 检索(工具) → 综合(LLM) → 输出</span></span></code></pre></div><p><strong>代码框架</strong>: LangChain、LangGraph、Crew AI</p><p><strong>关键技巧</strong>: 使用结构化输出（JSON/XML）确保步骤间数据完整性</p><h3 id="_2-routing-路由" tabindex="-1">2. Routing（路由） <a class="header-anchor" href="#_2-routing-路由" aria-label="Permalink to &quot;2. Routing（路由）&quot;">​</a></h3><p><strong>路由机制</strong>:</p><table tabindex="0"><thead><tr><th>类型</th><th>特点</th><th>适用场景</th></tr></thead><tbody><tr><td><strong>LLM-based</strong></td><td>灵活，可处理模糊输入</td><td>意图分类、复杂决策</td></tr><tr><td><strong>Embedding-based</strong></td><td>语义匹配</td><td>知识库路由、相似度检索</td></tr><tr><td><strong>Rule-based</strong></td><td>快速、确定性</td><td>关键词匹配、结构化数据</td></tr><tr><td><strong>ML-based</strong></td><td>专业分类器</td><td>高精度特定场景</td></tr></tbody></table><p><strong>示例</strong>:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>用户: &quot;我想查下订单&quot; → LLM分类 → &quot;订单状态&quot; → 路由到订单处理Agent</span></span>
<span class="line"><span>用户: &quot;这个功能怎么用&quot; → LLM分类 → &quot;产品信息&quot; → 路由到搜索Agent</span></span></code></pre></div><h3 id="_3-parallelization-并行化" tabindex="-1">3. Parallelization（并行化） <a class="header-anchor" href="#_3-parallelization-并行化" aria-label="Permalink to &quot;3. Parallelization（并行化）&quot;">​</a></h3><p><strong>核心思想</strong>: 独立子任务并行执行，减少总延迟</p><p><strong>模式</strong>:</p><ul><li><strong>Map-Reduce</strong>: 并行处理 → 结果聚合</li><li><strong>分叉-合并</strong>: 多分支并行 → 汇合综合</li></ul><h3 id="_4-reflection-反思" tabindex="-1">4. Reflection（反思） <a class="header-anchor" href="#_4-reflection-反思" aria-label="Permalink to &quot;4. Reflection（反思）&quot;">​</a></h3><p><strong>Agent 自我修正循环</strong>:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>生成输出 → 自我评估 → 发现问题 → 修正 → 再次评估</span></span></code></pre></div><p><strong>关键</strong>: 给 Agent 提供评估标准和批评提示</p><h3 id="_5-tool-use-工具调用" tabindex="-1">5. Tool Use（工具调用） <a class="header-anchor" href="#_5-tool-use-工具调用" aria-label="Permalink to &quot;5. Tool Use（工具调用）&quot;">​</a></h3><p><strong>工具类型</strong>:</p><ul><li><strong>信息获取</strong>: 搜索、数据库查询、RAG</li><li><strong>计算</strong>: 数学计算、代码执行</li><li><strong>操作</strong>: 发送消息、创建工单、文件操作</li><li><strong>API集成</strong>: 第三方服务调用</li></ul><h3 id="_6-planning-规划" tabindex="-1">6. Planning（规划） <a class="header-anchor" href="#_6-planning-规划" aria-label="Permalink to &quot;6. Planning（规划）&quot;">​</a></h3><p><strong>规划策略</strong>:</p><ul><li><strong>任务分解 (Task Decomposition)</strong>: 目标 → 子目标树</li><li><strong>链式规划 (Chain of Thought)</strong>: 逐步推理</li><li><strong>树形规划 (Tree of Thought)</strong>: 多路径探索</li></ul><h3 id="_7-multi-agent-collaboration-多智能体协作" tabindex="-1">7. Multi-Agent Collaboration（多智能体协作） <a class="header-anchor" href="#_7-multi-agent-collaboration-多智能体协作" aria-label="Permalink to &quot;7. Multi-Agent Collaboration（多智能体协作）&quot;">​</a></h3><p><strong>协作模式</strong>:</p><table tabindex="0"><thead><tr><th>模式</th><th>说明</th></tr></thead><tbody><tr><td><strong>合作</strong></td><td>多个 Agent 协同完成共同目标</td></tr><tr><td><strong>对抗</strong></td><td>Agent 间博弈（如代码评审）</td></tr><tr><td><strong>层次</strong></td><td>协调者 Agent + 专司机 Agent</td></tr></tbody></table><p><strong>框架</strong>: LangGraph（状态图）、Microsoft Autogen、Google ADK</p><hr><h2 id="与现有文档的关系" tabindex="-1">与现有文档的关系 <a class="header-anchor" href="#与现有文档的关系" aria-label="Permalink to &quot;与现有文档的关系&quot;">​</a></h2><p>本文档是 Agent 设计模式的体系化概览。建议结合以下文档深入学习：</p><ul><li><a href="./">Agent 模式索引</a> - ReAct/Plan-Execute 等工程模式</li><li><a href="./agent-course.html">Agent Course 学习笔记</a> - Agent 核心理论框架</li><li><a href="./workflow-patterns.html">Workflow Patterns</a> - 工作流模式实践</li></ul><hr><h2 id="相关资源" tabindex="-1">相关资源 <a class="header-anchor" href="#相关资源" aria-label="Permalink to &quot;相关资源&quot;">​</a></h2><ul><li><a href="https://adp.xindoo.xyz/" target="_blank" rel="noreferrer">Agentic Design Patterns 原书</a> - 中文翻译 by xindoo</li><li><a href="https://langchain-ai.github.io/langgraph/" target="_blank" rel="noreferrer">LangGraph</a> - 状态化 Agent 框架</li><li><a href="https://microsoft.github.io/autogen/" target="_blank" rel="noreferrer">Microsoft Autogen</a> - 多 Agent 协作框架</li><li><a href="https://google.github.io/adk-docs/" target="_blank" rel="noreferrer">Google ADK</a> - Google Agent 开发工具包</li></ul>`,52)])])}const f=a(o,[["render",d]]);export{m as __pageData,f as default};
